	key, err := requiredString(obj, "key", lineNo)
	if err != nil {
		return err
	}
	if key == "" {
		return &InputError{Line: lineNo, Reason: `field "key" must be a non-empty string`}
	}
	eventTime, err := requiredNonNegInt64(obj, "time", lineNo)
	if err != nil {
		return err
	}
	value, err := requiredInt64(obj, "value", lineNo)
	if err != nil {
		return err
	}

	if watermark != nil && eventTime < *watermark {
		fmt.Fprintf(lateLog, "line %d: late event time=%d is below current watermark %d, skipped\n", lineNo, eventTime, *watermark)
		return nil
	}

	start, end, err := windowBounds(eventTime, windowMillis, key)
	if err != nil {
		return &InputError{Line: lineNo, Reason: err.Error()}
	}

	id := windowID{start: start, key: key}
	st := windows[id]
	if st == nil {
		st = &windowState{end: end}
		windows[id] = st
	}
	if st.count == math.MaxInt64 {
		return &InputError{Line: lineNo, Reason: fmt.Sprintf("event count overflow for key %q window [%d,%d)", key, start, end)}
	}
	if sumOverflows(st.sum, value) {
		return &InputError{Line: lineNo, Reason: fmt.Sprintf("cumulative sum overflow for key %q window [%d,%d): %d + %d", key, start, end, st.sum, value)}
	}
	st.count++
	st.sum += value
	return nil
}

func processWatermark(obj map[string]json.RawMessage, lineNo int, windows map[windowID]*windowState, watermark **int64, out io.Writer) error {
	next, err := requiredNonNegInt64(obj, "time", lineNo)
	if err != nil {
		return err
	}
	if *watermark != nil {
		if next < **watermark {
			return &InputError{Line: lineNo, Reason: fmt.Sprintf("watermark moved backwards from %d to %d", **watermark, next)}
		}
	}
	*watermark = &next

	type pending struct {
		id windowID
		st *windowState
	}
	var ready []pending
	for id, st := range windows {
		if st.end <= next {
			ready = append(ready, pending{id: id, st: st})
		}
	}
	sort.Slice(ready, func(i, j int) bool {
		if ready[i].st.end != ready[j].st.end {
			return ready[i].st.end < ready[j].st.end
		}
		return ready[i].id.key < ready[j].id.key
	})
	for _, p := range ready {
		result := AggregateResult{
			Key:   p.id.key,
			Start: p.id.start * windowMillisOf(windows, p),
			End:   p.st.end,
			Count: p.st.count,
			Sum:   p.st.sum,
		}
		encoded, err := json.Marshal(result)
		if err != nil {
			return err
		}
		if _, err := out.Write(append(encoded, '\n')); err != nil {
			return err
		}
		delete(windows, p.id)
	}
	return nil
}

func windowBounds(eventTime, windowMillis int64, key string) (start, end int64, err error) {
	start = eventTime / windowMillis
	endU, carry := bits.Add64(uint64(start), uint64(windowMillis), 0)
	if carry != 0 || endU > math.MaxInt64 {
		return 0, 0, fmt.Errorf("window end overflow for key %q: start=%d window=%d", key, start, windowMillis)
	}
	return start, int64(endU), nil
}

func sumOverflows(sum, value int64) bool {
	if value > 0 {
		return sum > math.MaxInt64-value
	}
	if value < 0 {
		return sum < math.MinInt64-value
	}
	return false
}

func requiredString(obj map[string]json.RawMessage, field string, lineNo int) (string, error) {
	raw, ok := obj[field]
	if !ok {
