		`{"type":"event","key":"alpha","time":1200,"value":2}`,
		`{"type":"event","key":"zeta","time":1100,"value":3}`,
		`{"type":"event","key":"mid","time":900,"value":0}`,
		`{"type":"watermark","time":3000}`,
